#include <cstdint>
#include <optional>
#include <string>
#include <vector>

struct Section { std::string name; std::uint32_t virtualAddress; };
struct Headers { std::uint16_t machine; std::uint32_t entryPoint; std::uint64_t imageBase; std::vector<Section> sections; };

namespace
{
    // Reads `size` bytes little-endian at `at`, or nothing if they are not all inside the file.
    std::optional<std::uint64_t> read(const std::vector<std::uint8_t>& f, std::uint64_t at, int size)
    {
        if (at > f.size() || static_cast<std::uint64_t>(size) > f.size() - at) return std::nullopt;
        std::uint64_t v{ 0 };
        for (int i{ size - 1 }; i >= 0; --i) v = (v << 8) | f[static_cast<std::size_t>(at) + static_cast<std::size_t>(i)];
        return v;
    }
}

std::optional<Headers> parseHeaders(const std::vector<std::uint8_t>& file)
{
    if (read(file, 0, 2) != 0x5A4D) return std::nullopt;                       // "MZ"
    const auto lfanew{ read(file, 0x3C, 4) };
    if (!lfanew || read(file, *lfanew, 4) != 0x00004550) return std::nullopt;    // "PE\0\0"

    const auto machine{ read(file, *lfanew + 4, 2) };
    const auto sectionCount{ read(file, *lfanew + 6, 2) };
    const auto optionalSize{ read(file, *lfanew + 20, 2) };
    const std::uint64_t optional{ *lfanew + 24 };
    if (!machine || !sectionCount || !optionalSize) return std::nullopt;
    if (read(file, optional, 2) != 0x20B) return std::nullopt;                  // PE32+
    const auto entry{ read(file, optional + 16, 4) };
    const auto imageBase{ read(file, optional + 24, 8) };
    if (!entry || !imageBase) return std::nullopt;

    Headers h{ static_cast<std::uint16_t>(*machine), static_cast<std::uint32_t>(*entry), *imageBase, {} };
    const std::uint64_t table{ optional + *optionalSize };
    for (std::uint64_t i{ 0 }; i < *sectionCount; ++i)
    {
        const std::uint64_t entryAt{ table + i * 40 };
        if (entryAt > file.size() || 40 > file.size() - entryAt) return std::nullopt;   // the whole entry must be there
        const auto va{ read(file, entryAt + 12, 4) };
        std::string name;
        for (int k{ 0 }; k < 8 && file[static_cast<std::size_t>(entryAt) + static_cast<std::size_t>(k)] != 0; ++k)
            name += static_cast<char>(file[static_cast<std::size_t>(entryAt) + static_cast<std::size_t>(k)]);
        h.sections.push_back({ name, static_cast<std::uint32_t>(*va) });
    }
    return h;
}

