#include <cstring>
// Builds a small but well-formed set of PE headers: e_lfanew 0x80, an optional header of 0xF0 bytes, and the given sections.
static std::vector<std::uint8_t> makePe(std::vector<std::pair<std::string, std::uint32_t>> sections)
{
    std::vector<std::uint8_t> f(0x80 + 24 + 0xF0 + sections.size() * 40, 0);
    auto put = [&](std::size_t at, std::uint64_t v, int n) { for (int i{ 0 }; i < n; ++i) f[at + i] = static_cast<std::uint8_t>(v >> (8 * i)); };
    f[0] = 'M'; f[1] = 'Z';
    put(0x3C, 0x80, 4);
    f[0x80] = 'P'; f[0x81] = 'E';
    put(0x84, 0x8664, 2);
    put(0x86, sections.size(), 2);
    put(0x94, 0xF0, 2);
    put(0x98, 0x20B, 2);
    put(0x98 + 16, 0x12A0, 4);
    put(0x98 + 24, 0x140000000ull, 8);
    for (std::size_t i{ 0 }; i < sections.size(); ++i)
    {
        const std::size_t at{ 0x98 + 0xF0 + i * 40 };
        std::memcpy(&f[at], sections[i].first.data(), sections[i].first.size());
        put(at + 12, sections[i].second, 4);
    }
    return f;
}
TEST("a well-formed file")
{
    const auto h{ parseHeaders(makePe({ { ".text", 0x1000 }, { ".rdata", 0x5000 }, { ".data", 0x7000 } })) };
    CHECK(h.has_value());
    CHECK_EQ(h->machine, std::uint16_t{ 0x8664 });
    CHECK_EQ(h->entryPoint, 0x12A0u);
    CHECK_EQ(h->imageBase, 0x140000000ull);
    CHECK_EQ(h->sections.size(), std::size_t{ 3 });
    CHECK_EQ(h->sections[1].name, std::string(".rdata"));
    CHECK_EQ(h->sections[2].virtualAddress, 0x7000u);
}
TEST("an eight-character name has no terminator") { const auto h{ parseHeaders(makePe({ { ".textbss", 0x1000 } })) }; CHECK_EQ(h->sections[0].name, std::string(".textbss")); }
TEST("not MZ") { auto f{ makePe({}) }; f[0] = 'X'; CHECK(!parseHeaders(f)); }
TEST("not PE") { auto f{ makePe({}) }; f[0x80] = 'Q'; CHECK(!parseHeaders(f)); }
TEST("32-bit headers are refused") { auto f{ makePe({}) }; f[0x98] = 0x0B; f[0x99] = 0x01; CHECK(!parseHeaders(f)); }
TEST("e_lfanew points outside the file") { auto f{ makePe({}) }; f[0x3C] = 0xFF; f[0x3D] = 0xFF; CHECK(!parseHeaders(f)); }
TEST("the section table is cut short") { auto f{ makePe({ { ".text", 0x1000 } }) }; f.resize(f.size() - 10); CHECK(!parseHeaders(f)); }
TEST("tiny or empty files") { CHECK(!parseHeaders({})); CHECK(!parseHeaders({ 'M', 'Z' })); }

